insert into ve_social_slots (brand_slug,slot_at,channels,kind,title,caption,links,assets,status,manual_steps,batch,proposed_by,sound) select 'vegans-explore', '2026-11-16 09:00 America/New_York'::timestamptz, ARRAY['instagram','facebook','tiktok']::text[], 'carousel', 'Founding 1: Your week', 'Monday, 6:47 PM. Nothing to eat. Here is how your week goes once you join Vegans Explore.

Find Vegan places near you in a tap. Check in for points. Press play on a free show. Make Friday plans from the places you saved. Find a Vegan event on Saturday. Give your points to a cause on Sunday.

All of it is free. Joining is a short survey, and you get 250 welcome points.

Here is the catch: join before midnight Eastern on January 1, 2027, and you are a Founding Member. It stays on your profile for good. After that, it is gone.

South Florida, Central Florida, North Florida, Atlanta, Washington, D.C., Maryland, Virginia, West Virginia, Delaware, New York, Philadelphia, Boston, Austin, Denver, Los Angeles, San Francisco, Portland, Seattle, London.

Tap the link in bio to join free.

