insert into ve_social_slots (brand_slug,slot_at,channels,kind,title,caption,links,assets,status,manual_steps,batch,proposed_by,sound) select 'vegans-explore', '2026-11-30 09:00 America/New_York'::timestamptz, ARRAY['instagram','facebook','tiktok']::text[], 'carousel', 'Founding 3: Be one of the first', 'This title ends January 1. After that, it is gone. No exceptions.

Join Vegans Explore before midnight Eastern on January 1, 2027 and you are a Founding Member. It stays on your profile for good.

Joining is free: a short survey, and you get 250 welcome points. Find Vegan places near you, check in and earn points, go to Vegan events, follow a free Guide for every step, and press play on free shows every week.

From South Florida to Seattle, Atlanta to London, your city is already here.

Tap the link in bio to join free. The clock is on.

