insert into ve_social_slots (brand_slug,slot_at,channels,kind,title,caption,links,assets,status,manual_steps,batch,proposed_by,sound) select 'vegans-explore', '2026-12-07 09:00 America/New_York'::timestamptz, ARRAY['instagram','facebook','tiktok']::text[], 'carousel', 'Founding 4: Your city', 'Find your city on slide 1. Your Vegan community is already there.

